+    background-color: #2563eb;
+}
+
+.switch input:checked + .slider::before {
+    transform: translateX(20px);
+}
+
+/* Channel list */
+.channel-list {
+    display: flex;
+    flex-direction: column;
+    gap: 0.5rem;
+}
+
+.channel-item {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    padding: 0.4rem 0.5rem;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+.channel-item:hover {
+    background: #f9fafb;
+}
+
+/* Buttons */
+.button-group {
+    display: flex;
+    gap: 0.75rem;
+    margin-top: 1.5rem;
+}
+
+.btn {
+    padding: 0.6rem 1.2rem;
+    border: none;
+    border-radius: 6px;
+    font-size: 0.9rem;
+    font-weight: 500;
+    cursor: pointer;
+    transition: background-color 0.2s, transform 0.1s;
+}
+
+.btn:active {
+    transform: scale(0.98);
+}
+
+.btn-primary {
+    background-color: #2563eb;
+    color: white;
+}
+
+.btn-primary:hover {
+    background-color: #1d4ed8;
+}
+
+.btn-secondary {
+    background-color: #f3f4f6;
+    color: #374151;
+    border: 1px solid #d1d5db;
+}
+
+.btn-secondary:hover {
+    background-color: #e5e7eb;
+}
+
+.btn-danger {
+    background-color: #dc2626;
+    color: white;
+}
+
+.btn-danger:hover {
+    background-color: #b91c1c;
+}
+
+.btn-sm {
+    padding: 0.35rem 0.75rem;
+    font-size: 0.8rem;
+}
+
+/* Expandable panel */
+.expandable-panel {
+    border: 1px solid #e5e7eb;
+    border-radius: 8px;
+    margin-bottom: 1.5rem;
+    overflow: hidden;
+}
+
+.panel-header {
+    width: 100%;
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 0.85rem 1rem;
+    background: #f9fafb;
+    border: none;
+    cursor: pointer;
+    font-size: 0.95rem;
+    font-weight: 500;
+}
+
+.panel-header:hover {
+    background: #f3f4f6;
+}
+
+.panel-body {
+    padding: 1rem;
+    border-top: 1px solid #e5e7eb;
+}
+
+/* Status indicator */
+.status-indicator {
+    padding: 0.2rem 0.6rem;
+    border-radius: 12px;
+    font-size: 0.8rem;
+    font-weight: 500;
+}
+
+.status-enabled {
+    background-color: #d1fae5;
+    color: #065f46;
+}
+
+.status-disabled {
+    background-color: #fee2e2;
+    color: #991b1b;
+}
+
+/* Sessions table */
+.table-container {
+    overflow-x: auto;
+}
+
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    font-size: 0.9rem;
+}
+
+.sessions-table th,
+.sessions-table td {
+    padding: 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid #e5e7eb;
+}
+
+.sessions-table th {
+    background: #f9fafb;
+    font-weight: 600;
+    color: #4b5563;
+}
+
+.current-badge {
+    background: #dbeafe;
+    color: #1e40af;
+    padding: 0.2rem 0.5rem;
+    border-radius: 4px;
+    font-size: 0.75rem;
+    font-weight: 500;
+}
+
+/* Modal */
+.modal-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.modal {
+    background: white;
+    border-radius: 12px;
+    padding: 1.5rem;
+    max-width: 420px;
+    width: 90%;
+    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.15);
+}
+
+.modal h3 {
+    margin-top: 0;
+}
+
+/* Radio group */
+.radio-group {
+    display: flex;
+    gap: 1rem;
+    flex-wrap: wrap;
+}
+
+.radio-item {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    padding: 0.5rem 0.75rem;
+    border: 1px solid #d1d5db;
+    border-radius: 6px;
+    cursor: pointer;
+    transition: border-color 0.2s;
+}
+
+.radio-item:has(input:checked) {
+    border-color: #2563eb;
+    background: #eff6ff;
+}
+
+/* Appearance preview */
+.appearance-preview {
+    border: 1px solid #e5e7eb;
+    border-radius: 8px;
+    padding: 1.5rem;
+    margin-bottom: 1rem;
+    transition: all 0.3s;
+}
+
+.preview-header {
+    font-weight: 600;
+    margin-bottom: 0.75rem;
+}
+
+.preview-text {
+    margin-bottom: 0.75rem;
+    line-height: 1.5;
+}
+
+.preview-button {
+    padding: 0.4rem 0.8rem;
+    border-radius: 4px;
+    border: 1px solid #d1d5db;
+    cursor: pointer;
+}
+
+/* Preview theme variants */
+.preview-theme-dark {
+    background-color: #1f2937;
+    color: #f9fafb;
+    border-color: #374151;
+}
+
+.preview-theme-dark .preview-button {
+    background: #374151;
+    color: #f9fafb;
+    border-color: #4b5563;
+}
+
+.preview-theme-light {
+    background-color: #ffffff;
+    color: #111827;
+}
+
+.preview-theme-system {
+    background: linear-gradient(135deg, #ffffff 50%, #1f2937 50%);
+    color: #111827;
+}
+
+/* Preview font sizes */
+.preview-font-small {
+    font-size: 0.8rem;
+}
+
+.preview-font-medium {
+    font-size: 1rem;
+}
+
+.preview-font-large {
+    font-size: 1.2rem;
+}
+
+/* Preview compact */
+.preview-compact {
+    padding: 0.75rem;
+}
+
+.preview-compact .preview-header {
+    margin-bottom: 0.4rem;
+}
+
+.preview-compact .preview-text {
+    margin-bottom: 0.4rem;
+}
+
+/* Toast */
+.toast {
+    padding: 0.75rem 1rem;
+    border-radius: 8px;
+    margin-bottom: 1rem;
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    animation: slideIn 0.3s ease;
+}
+
+.toast.success {
+    background-color: #d1fae5;
+    color: #065f46;
+    border: 1px solid #a7f3d0;
+}
+
+.toast.info {
+    background-color: #dbeafe;
+    color: #1e40af;
+    border: 1px solid #bfdbfe;
+}
+
+.toast-close {
+    background: none;
+    border: none;
+    font-size: 1.2rem;
+    cursor: pointer;
+    opacity: 0.7;
+}
+
+.toast-close:hover {
+    opacity: 1;
+}
+
+.error-text {
+    color: #dc2626;
+    font-size: 0.85rem;
+    margin: 0.5rem 0;
+}
+
+.info-text {
+    color: #6b7280;
+    font-size: 0.85rem;
+}
+
+@keyframes slideIn {
+    from { opacity: 0; transform: translateY(-10px); }
+    to { opacity: 1; transform: translateY(0); }
+}
+
+/* Responsive */
+@media (max-width: 768px) {
+    .settings-container {
+        flex-direction: column;
+        padding: 1rem;
+    }
+
+    .settings-sidebar {
+        width: 100%;
+    }
+
+    .settings-sidebar ul {
+        display: flex;
+        overflow-x: auto;
+        gap: 0.25rem;
+    }
+
+    .settings-sidebar li {
+        white-space: nowrap;
+    }
+
+    .settings-sidebar li.active {
+        border-left: none;
+        border-bottom: 3px solid #2563eb;
+    }
+}
+

